# Q13: appends Q13a-Q13f, annotates Q3b/Q1b lobe entries, applies the Q14 wording fixes (Q14a/Q14h/Q14m), recipe/caveats/interpretation (idempotent). python3 -I build_report_q13.py
import json
p='/output/report.json'; r=json.load(open(p))
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q13')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q13:')]
r['caveats']=[x for x in r['caveats'] if not x.startswith('Q13:')]
i=r['interpretation'].find('\n\nQ13:'); r['interpretation']=r['interpretation'][:i] if i>=0 else r['interpretation']
A=lambda n,v:{"name":n,"value":v}
common=[A("position","Soutflow = (-0.21,-4.48)\" from the phase centre (scripts/q3_pos.py), the blue-lobe peak of HCN 3-2; apertures are circles of radius 0.5-2\" on cubes convolved channel-wise to a circular 1.05\" beam (Xb4d native 0.95x0.75\", Xb4b native 0.25\")"),
 A("windows","radio velocities in each line's own frame (rest 265.886434 HCN, 267.557626 HCO+ 3-2): E window 2375-2575 km/s (= Vsys-400..-200, team-b), blueB 2300-2575, core 2575-2875, red mirror 2975-3175; per-pixel linear baseline from line-free channels (HCN 1380-2100; HCO+ 1280-1680, 1880-2100)"),
 A("excess","E = HCN - k*HCO+, k = 0.574 (HCN/HCO+ fitted on 2575-2875 at the lobe in Xb4d, Q3b) or the array's own core ratio; mean Jy/beam km/s in the aperture"),
 A("noise","scatter (robust MAD) of the same quantity in 300 random apertures of the same radius within 7.5\" of the centre, >=3\" from N, S, Bridge, Soutflow, W clump and with HCO+ core <0.25 Jy/beam km/s; more conservative than a pixel-rms of the empty field")]
def R(q,v,u,unit,conf,ev,tgt,extra=()):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"confidence":conf,"evidence":ev,"target":tgt,"assumptions":common+list(extra)})
# ---------- Q14 wording fixes (reviewer, round 2)
for x in r['results']:
    q=x['quantity']
    if q.startswith('Q14a') and not x['value'].startswith('AUTHORITATIVE'):
        v=x['value']
        old=' S - N at 6.3x3.8" (Xb4f) = 0.0196+-0.0043 (4.6 sigma), Xb4d 4.45": 3.0 sigma, 1.7": 0.9 sigma.'
        assert old in v
        v=v.replace(old,'')
        i=v.find(' [Q14i supersedes'); v=v[:i] if i>=0 else v
        x['value']=('AUTHORITATIVE S-N (Q14i, whole-line template amplitudes + empirical off-source null): CH3OH/HCO+ S-N = 2.8-3.0 sigma per array at 6.3x3.8" and <=1.5 sigma at <=4.45" (MODERATE, not firm; the CH3OH peak lies 1-3" from N and S towards the Bridge/W clump). The 4.6 sigma quoted in earlier versions is the S detection alone (Xb4f, 6.3x3.8"), not S-N. Region/beam sequence of the fixed-position ratios (cross-check, older estimator): '+v).strip()
    if q.startswith('Q14h') and 'not compared' not in x['value']:
        x['value']+=" EXTERNAL INPUTS AND WHAT WAS NOT DONE: X(CH3OH) and X(CS) were NOT compared with the Harada+2018 fractional abundances (relative to H2/CO) - only the 96.74 GHz CH3OH/HCO+ intensities were compared (item 3); the dust N(H2) behind X assumes kappa(346 GHz)=0.02 cm2 per g gas (factor 2) and Td 20-50 K (factor 3.3); Harada+2018 (ApJ 855, 49) is used as an external assumption for its Table 1-3,13 setup/intensities."
        x['assumptions'].append(A("Harada+2018","ApJ 855, 49 (arXiv:1801.05941) Tables 1-3, 13: 12-m-only Band 3 CH3OH, 1.7\" convolution, +-150 km/s sums; no abundance comparison made"))
        x['assumptions'].append(A("dust","kappa(346 GHz)=0.02 cm2 per g gas, mu=2.8, Td 20-50 K (Q14m)"))
    if q.startswith('Q14m') and 'NOT compared with the Harada' not in x['value']:
        x['value']+=" NOT compared with the Harada+2018 fractional abundances (relative to H2/CO) here: consistency/inconsistency with the published range is untested (within the factor-3 Td and factor-2 kappa uncertainty a comparison would be weak). N(H2) assumes kappa(346 GHz)=0.02 cm2 per g gas and Td 20-50 K."
        x['assumptions'].append(A("Harada+2018","external published abundances not used or compared; Harada Table 13 intensities used only in Q14g"))
# ---------- Q13 entries
R("Q13a: S-outflow blue-lobe HCN excess E = HCN-k*HCO+ (2375-2575 km/s) in Xb4d vs Xb4b at the SAME 1.05\" beam, windows and apertures; reconciliation of 'Xb4d 6.2 sigma' with 'Xb4b 1 sigma'",
"Xb4d: E (Jy/beam km/s, mean in aperture, k=0.574) = 0.161+-0.044 (3.7 sigma, r=0.5\"), 0.115+-0.026 (4.4 sigma, r=1.0\"), 0.074+-0.017 (4.3 sigma, r=1.5\"), 0.038+-0.013 (3.0 sigma, r=2.0\"); 0 of 300 random apertures (r=0.5 and 1.0\") reach E (p<0.003); the red mirror window (2975-3175) gives -0.062+-0.04 (r=0.5\") and +0.019+-0.027 (r=1\"): zero. Converted to flux 0.115 x 2.5 beams = 0.29 Jy km/s (r=1\") reproduces team-b p0006-r02 E=0.262+-0.042 (k 0.534); our noise is 1.6x larger (random apertures include baseline/disk residual) so the same excess is 4.4 sigma here instead of 6.2 sigma: the difference is only the noise estimator. Xb4b (smoothed 1.05\"): E = 0.107+-0.068 (1.6 sigma, r=0.5\"), 0.035+-0.046 (0.8 sigma, 1\"), 0.002+-0.031 (1.5\"), -0.006+-0.026 (2\"); 7-53 of 300 random apertures exceed it. If Xb4b recovered all of the Xb4d excess it would be detected at only 2.4, 2.5, 2.4, 1.5 sigma (Xb4b noise is 1.5-1.8x Xb4d at this beam), so the 'Xb4b 1 sigma' is a 1-2 sigma downward fluctuation or partial resolving-out, not a contradiction: recovery R=E(Xb4b)/E(Xb4d) = 0.67+-0.46 (0.5\"), 0.31+-0.41 (1\"), 0.02+-0.42 (1.5\"), -0.16+-0.69 (2\"); R=1 is disfavoured at 0.7, 1.7, 2.3, 1.7 sigma, i.e. no more than 2.3 sigma. Line recovery at the lobe (r=1\"): HCN blue window 0.58+-0.22 (r=1.5\": 0.37+-0.30), HCO+ blue 1.14+-0.49, HCN core 1.10+-0.34, HCO+ core 1.00+-0.33; at S 0.85+-0.11 (HCN), 0.92+-0.07 (HCO+), N 0.99+-0.03/0.99+-0.04, Bridge 0.82/0.86 (+-0.1). VERDICT: Xb4d and Xb4b are consistent (difference 0.7-2.0 sigma); the trend of R to smaller values with larger apertures is the signature expected for gas extended on >1\" scales and partly filtered by the 0.25\" configuration (consistent with the 55+-25% HCN recovery of Q3), but it is not demanded by the data; Xb4b cannot confirm or refute the excess.",
"E errors from random apertures (see assumptions); Xb4b/Xb4d recovery R +-0.4","Jy/beam km/s","medium",
"scripts/q13a_xb4_compare.py, q13a2_recovery.py -> out/q13/q13a.log, q13a_table.csv, q13a2_recovery.csv, q13a2_E_apertures.csv, q13a_maps_{Xb4d,Xb4b}.npz","Soutflow",
[A("team-b comparison","team-b p0006-r01/r02 values (/snapshots/team-b-s07/out/q11r2/s72a.txt): E=0.262+-0.042 Jy km/s (6.3 sigma) in r=1\" in -405..-205 km/s about 2780; aperture-flux = mean x 2.5 beams")])
R("Q13b: HCN/HCO+ 3-2 ratio of the lobe versus window, aperture and array (reconciles 1.0-1.4, 1.7-1.8 and 0.7-0.8)",
"Xb4d (Xb4b in brackets) HCN/HCO+ (Tb = flux ratio, same beam): E window 2375-2575: 1.31+-0.31 (1.19+-0.52) at r=0.5\", 1.77+-0.50 (0.90+-0.45) at 1.0\", 2.2+-0.8 at 1.5\"; blueB 2300-2575: 1.29+-0.33 (1.29+-0.66), 1.81+-0.57 (1.03+-0.61); lobe core 2575-2875: 0.60+-0.12 (0.69+-0.26), 0.59+-0.14 (0.66+-0.24), 0.51+-0.13; whole broad component 2300-2875: 0.74+-0.15 (0.80+-0.30), 0.76+-0.18 (0.71+-0.27), 0.63+-0.15. So 1.0-1.4 (Q3b fixed window), 1.3-1.8 (this E window) and 0.7-0.8 (whole component) are all the same data: the ratio is high only in the blue 2300-2575 km/s window (ratio of the wing to the local core ratio 0.59: 2.2-3.0 +-0.8), because the HCN profile is broader/bluer than HCO+ (the two lines do not share kinematics; Q3b dchi2=109/4). HCO+ in the E window: 5.2 (r=0.5\") / 4.2 sigma (1\") in Xb4d, 2.9 / 2.8 sigma in Xb4b. Xb4b ratios agree with Xb4d within 1 sigma at every aperture (errors 0.3-0.6).",
"+-0.3-0.6 (random-aperture noise); window choice is the dominant systematic","ratio","medium",
"scripts/q13d_ratio.py -> out/q13/q13d_ratio.csv","Soutflow",[])
R("Q13c: can the blue-lobe HCN excess be a blend? Species/HDO tests with their allowed fractions",
"(1) Blenders other than HDO: forward-modelled LTE ladders of CH3NH2, CH3OH, CH2NH, CH3CHO, CH3SH fitted to all other Band-6 channels at the lobe (Q3b, out/q3b/blend.log; c-C3H and l-C3H, HCN v2=1f and CH3CHO companions in team-b p0006-r02 s72c.txt): total blended fraction of the HCN flux <=0.10-0.18 in 2375-2575 (2 sigma envelope over T 15-120 K; <=0.42 at 2275-2375). (2) HDO 2(2,0)-3(1,3) 266.1611 GHz (Eu=157 K) is the only HDO line in the 250-266 GHz windows (catalogue dump: HDO 356.836 GHz, Eu 539 K, is the only other line in any band, undetectable); it lies -309.7 km/s from HCN, v_app = -309.7 + 1.00103 v_gas, i.e. gas at 2685-2885 km/s (the line core) would appear at 2375-2575: a blend is kinematically possible and has no second HDO line to test it. (3) Spectral test (22 km/s bins, 2100-2575 km/s; HDO template = HCO+ profile of the same aperture shifted by -309.7 km/s): residual HCN-k*HCO+ chi2 null/HDO-template/free-Gaussian wing/Gaussian+HDO = 68.8/34.5/20.4/20.3 (Xb4d r=0.5\"; 27 bins) and 122.3/42.8/22.2/21.9 (r=1\"); the HDO-with-gas-kinematics template is disfavoured against a free Gaussian (dchi2 14-21 for 2 extra parameters) and its share in the joint fit is -0.15+-0.38 (r=0.5\") / -0.16+-0.30 (r=1\") of E, i.e. <0.48 / <0.33 at 95%; Gaussian wing centre 2500-2506 km/s, sigma 93-117 km/s. In Xb4b the same fit is degenerate (HDO share 0.27+-0.28 / -0.19+-0.56). If the HDO line has arbitrary kinematics the spectrum alone allows 0-100%. (4) Chemical/spatial test: E in 2375-2575 per unit HCO+ emission of the parent-gas window (2685-2885): lobe 0.230 (E 4.9 sigma) vs 3 sigma limits S <0.027, N <0.014, Bridge <0.032, W clump <0.031 (E = 0.009+-0.024, 0.002, 0.013, -0.020 +-0.024 Jy/beam km/s there): a blend with an HDO/HCO+ ratio common to the regions is excluded; it requires a lobe-specific HDO enhancement of >=8.6x (S), >=16.9x (N), >=7.1x (Bridge), >=7.5x (W clump) relative to those regions (S nucleus: E <0.079 Jy/beam km/s at 3 sigma, 0.7x the lobe's 0.115 even though S has 6x more parent gas). SUMMARY OF THE BLEND-ALLOWED FRACTION of the HCN excess E: <=0.1-0.2 for all species except HDO; HDO with HCO+-like kinematics <0.33-0.48 (95%); HDO with arbitrary kinematics not constrained by the spectrum (<=1) but requiring a >=7-17x lobe-specific HDO enhancement. The HCO+ blue wing (4-5 sigma at 1.05\", not affected by HDO) stands independent of this question.",
"HDO share -0.16+-0.30 (Xb4d, r=1\"); other species <=0.10-0.18 (2 sigma upper envelope)","fraction","medium",
"scripts/q13b_hdo.py -> out/q13/q13b.log, q13b_template_fit.csv, q13b_hdo_ratio.csv; scripts/q3b_blend.py -> out/q3b/blend.log; line list from scripts/ident.py (out/splatalogue_raw.csv); s72c.txt of team-b","Soutflow, S, N, Bridge, Wclump",
[A("HDO frequency","266.1611 GHz, Eu=157.2 K, logA=-4.756 (JPL/CDMS dump in out/splatalogue_raw.csv)"),A("template","HDO assumed to share the gas velocity profile of HCO+ (same aperture) for the template test; no assumption for the arbitrary-kinematics statement")])
R("Q13d: HCN 4-3 (Xb47, no HDO line nearby) as an independent-transition check at the matched 4.5\" circular beam",
"Lobe aperture r=1\" at 4.5\" (Jy/beam km/s, baseline from line-free channels; random-aperture scatter): HCN 3-2 (Xb4d) blue 2375-2575: 0.375+-0.134 (2.8 sigma), core 4.05; HCN 4-3 (Xb47) blue 0.384+-0.118 (3.3 sigma), core 4.90. Tb ratios (4-3/3-2, same beam; 3-2 smoothed from Xb4d): HCN core 0.68+-0.15, blue window 0.58+-0.27 (S nucleus core 0.54+-0.07, N 0.55+-0.03, Bridge 0.53+-0.04). Maps at 4.5\": HCN 3-2 blue-window peak within 6\" of S = 0.41 Jy/beam km/s (2.1 sigma of the field pixel rms) at the lobe position (0.06\" from it); HCN 4-3 0.43 (2.8 sigma) at 2.5\" from it; both red mirrors <=2.5 sigma at other places. Prediction for the 4-3 blue window: real HCN wing with the core Tb ratio 0.453+-0.192; if the whole 3-2 excess were HDO (4-3 wing = k*HCO+ only) 0.110+-0.164; observed 0.384+-0.118: -0.3 sigma from 'real', +1.4 sigma from 'HDO-only'. HCO+ 4-3 could not be used (Xb47 spw18 baseline unreliable: blue window negative -0.96+-0.7 at S). VERDICT: consistent with the 3-2 excess being real HCN (same Tb ratio as the core), but the 4.5\" beam dilutes the lobe ~17x and the 4-3 detection is only 3 sigma: this is a weak, non-decisive check (HDO-only disfavoured at 1.4 sigma).",
"+-0.12-0.19 Jy/beam km/s (null scatter) -> discrimination 1.4 sigma","Jy/beam km/s, ratio","low",
"scripts/q13c_hcn43.py, q13c2_maps43.py, q13f_pred43.py -> out/q13/q13c.log, q13c_table.csv, q13c_spectra.csv, q13c2.log, q13f.log","Soutflow, S, N, Bridge",[A("beam","Xb47 (4.1-4.3x2.7-2.8\") and Xb4d convolved channel-wise to 4.5\" circular; per-channel beam table not applied (header beam)"),A("Tb","Tb = S/nu^2 for the same beam, (354.505/265.886)^2=1.778")])
R("Q13e: Xb4d clean mask and flux scale at the lobe velocities",
"The Xb4d clean masks (cube.I.mask) contain none of the lobe channels: mask fraction of the r=1\" lobe aperture is 0.000 in 2300-2575 km/s for both HCN (mask spans 2651-2929 km/s) and HCO+ (mask 1834-2950 in other places) versus 0.58/0.77 in 2575-2875. The blue-wing emission is therefore in uncleaned channels (dirty-beam flux scale, unknown epsilon<1 for diffuse emission), for both lines alike: the HCN/HCO+ ratio is not affected to first order but absolute wing fluxes are lower limits per beam; this is a systematic shared by team-b's numbers. Xb4b has no mask product.",
"not quantified (epsilon unknown without the dirty beam)","fraction","low","scripts/q13e_mask.py -> out/q13/q13e.log; team-b s72a.txt part (c)","Soutflow",[])
R("Q13f: SUMMARY: is the S-outflow blue-lobe HCN excess real dense wing gas? What survives, with blend-allowed fraction",
"(1) Detection: the HCN blue-lobe excess E over k*HCO+ is reproduced in Xb4d at 4.4 sigma (r=1\", 3.7-4.3 sigma for r=0.5-1.5\") with a conservative empirical null (0/300 random apertures; team-b 6.2 sigma with a smaller noise estimate) and absent in the red mirror (+0.019+-0.027). HCO+ itself shows the blue wing at 4.2-5.2 sigma (Xb4d, 1.05\"), independent of any HDO blend. (2) Xb4d vs Xb4b: consistent; Xb4b has 1.5-1.8x higher noise at 1.05\" so even full recovery gives only 2.4-2.5 sigma (observed 0.8-1.6); R(E)=0.3-0.7+-0.4 at r<=1\", falling to 0 at 1.5-2\" (R=1 disfavoured <=2.3 sigma): the data neither require nor exclude partial resolving-out of extended (>1\") excess. (3) Blend: all species other than HDO <=10-18% of E; HDO untestable by a companion line; with HCO+-like kinematics <33-48% (95%), any kinematics 0-100% but needing a lobe-specific >=7-17x HDO enhancement relative to S, N, Bridge, W clump; HCN 4-3 prediction test weakly favours real HCN (1.4 sigma). (4) What follows for the lobe: the dense-gas (HCO+, 4-5 sigma) blue lobe stands; its HCN/HCO+ is 1.3-1.8 (+-0.3-0.5) in the 2375-2575 window (2.2-3x the lobe-core 0.59), 0.74-0.76+-0.15 for the whole broad component, and 0.57 (=k) if E is entirely a blend: for a blended fraction f of E the E-window ratio is (HCN-f*E)/HCO+ = 1.78, 1.18, 0.58 for f=0, 0.5, 1 (Xb4d, r=1\"). The HCN-based dense-gas mass of the lobe (Q3b: 1.4e6-4.6e6 Msun, route A) falls by up to a factor 2-3 for f=1 (E is 57-67% of the HCN blue-window flux); the HCO+-based mass (1.9e6-6.5e6) is unchanged. CLASSIFICATION: dense (HCO+/HCN) gas in the southern blue lobe: supported (medium); the elevated HCN/HCO+ (>1) in the blue wing: probable but not proven (medium-low: Xb4b cannot confirm, HDO cannot be excluded for arbitrary kinematics, 4-3 check weak). Decisive tests not possible here: a second HDO transition (e.g. 225.9 or 241.6 GHz, not in this data) or deeper HCN/HCO+ 4-3 at <=1\".",
"E 4.4 sigma (Xb4d); blend fraction see Q13c; ratio see Q13b","","medium",
"out/q13/*, scripts/q13*.py, q3b_*.py","Soutflow",[])
# ---------- annotate Q3b lobe entries
for x in r['results']:
    q=x['quantity']
    if (q.startswith('Q3b: classification of the Soutflow candidate') or q.startswith('Q3b: HCN blue-side excess at Soutflow')) and '[Q13' not in x['value']:
        x['value']+=" [Q13 (round 3): the excess is reproduced at matched beam and apertures at 4.4 sigma in Xb4d with a conservative null; Xb4b is consistent (not an independent confirmation: expected S/N <=2.5 at full recovery); HDO share <0.33-0.48 for HCO+-like kinematics and a >=7-17x lobe-specific enhancement for any other kinematics; see Q13a-Q13f.]"
r['recipe'].append({"order":max(x['order'] for x in r['recipe'])+1,"stage":"modelling","description":"Q13: (1) q13a_xb4_compare.py: Xb4d and Xb4b cubes convolved channel-wise to 1.05\" circular, per-pixel linear baselines, window maps (E 2375-2575, blueB 2300-2575, core, red mirror), E=HCN-k*HCO+ (k 0.574 or own core), apertures r=0.5/1.0, noise from 300 random apertures; q13a2_recovery.py: Xb4b/Xb4d recovery per line/window/aperture (r 1-2\") and recovery R of E; (2) q13d_ratio.py: HCN/HCO+ vs window/aperture/array; (3) q13b_hdo.py: HDO 266.1611 template (HCO+ profile shifted -309.7 km/s) vs free Gaussian vs null on 22 km/s bins, HDO-per-HCO+ comparison between lobe, S, N, Bridge, W clump; (4) q13c_hcn43.py, q13c2_maps43.py, q13f_pred43.py: Xb47 HCN 4-3 vs Xb4d HCN 3-2 at a 4.5\" circular beam, prediction for real vs HDO-only; (5) q13e_mask.py: Xb4d clean-mask check; (6) build_report_q13.py.","scripts":["scripts/q13a_xb4_compare.py","scripts/q13a2_recovery.py","scripts/q13b_hdo.py","scripts/q13c_hcn43.py","scripts/q13c2_maps43.py","scripts/q13d_ratio.py","scripts/q13e_mask.py","scripts/q13f_pred43.py","scripts/build_report_q13.py"],"inputs":"/data Xb4d, Xb4b, Xb47 cubes (spw25,27 and Xb47 spw16,18) and Xb4d cube masks; out/splatalogue_raw.csv"})
r['caveats'].append("Q13: (a) E significance depends on the noise estimator: 4.4 sigma with the conservative random-aperture null (this work), 6.2 sigma with the smaller field-rms (team-b); (b) Xb4b has too little sensitivity at 1.05\" to confirm the excess (expected S/N 1.5-2.5 even at full recovery) and R decreases with aperture, consistent with partly resolved-out extended gas but not required; (c) HDO 266.161 GHz has no companion line in the data: for arbitrary kinematics the blend fraction is unconstrained by the spectrum, constrained only by the chemical argument (>=7-17x lobe-specific enhancement) and the weak 4-3 check; (d) the lobe channels are outside the Xb4d clean masks (uncleaned, dirty-beam flux scale); (e) HCO+ 4-3 unusable at the lobe (baseline), so no E at 4-3; (f) HCN/HCO+ in the lobe is window-dependent (0.6 core, 1.3-1.8 E window, 0.74 whole component), so a single ratio must not be used in RADEX without stating the window. Confirmation needs a second HDO line or HCN/HCO+ 4-3 at <=1\" with a clean mask extending to -400 km/s.")
r['interpretation']+="\n\nQ13: The southern blue lobe is a dense-gas feature (HCO+ 4-5 sigma, HCN excess 4.4 sigma at 1.05\" in Xb4d); Xb4b (1 sigma) is consistent with it because its 1.05\" sensitivity is too low and part of the excess may be extended; blends other than HDO are <=10-18%, and HDO would need to be lobe-specific by >=7-17x. We therefore keep 'dense gas in the S outflow' (medium) and treat HCN/HCO+>1 in the blue wing as probable but unproven; the whole-component ratio is 0.74+-0.15, not much above the nuclei (0.4-0.8)."
json.dump(r,open(p,'w'),indent=1)
